package com.tcrrry.diary;
import android.graphics.*;import android.view.*;import android.widget.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import java.util.function.Consumer;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @org.robolectric.annotation.GraphicsMode(org.robolectric.annotation.GraphicsMode.Mode.NATIVE) @Config(sdk=35,manifest=Config.NONE,qualifiers="w411dp-h724dp-420dpi")
public class ImmersiveDiaryPanelTest {
    protected ImmersiveDiaryPanel panel;protected JSONObject data;protected int reports;protected String lastPeriod;protected boolean closed;
    @Before public void setUp()throws Exception{data=fixture();android.app.Activity activity=Robolectric.buildActivity(android.app.Activity.class).setup().get();panel=new ImmersiveDiaryPanel(activity,new ImmersiveDiaryPanel.Actions(){public void report(String period,String day,Consumer<JSONObject> ready,Consumer<String> error){reports++;lastPeriod=period;ready.accept(data);}public void enabled(boolean on){}public void network(boolean on){}public void exportData(){}public void clearData(Runnable done){}public void artwork(String id,Consumer<Bitmap> ready){String path=System.getProperty("diary.preview.art");if(path!=null&&id.matches("test[0-9]+"))ready.accept(BitmapFactory.decodeFile(new java.io.File(path,id+".jpg").getPath()));}public void closed(ImmersiveDiaryPanel p){closed=true;}});activity.setContentView(panel.getView());layout();}
    protected JSONObject fixture()throws Exception{JSONArray daily=new JSONArray();for(int i=0;i<24;i++)daily.put(new JSONObject().put("id","test"+i%3).put("visit","visit"+i).put("title",new String[]{"晚风经过的地方","A Quiet Morning","把日子慢慢听完"}[i%3]).put("artist","示例歌手 "+(char)('A'+i%3)).put("album","示例专辑").put("duration",240000).put("start",1792880000000L+i*300000).put("end",1792880220000L+i*300000).put("ms",220000).put("zone","Asia/Shanghai"));return new JSONObject().put("today","2026-10-25").put("selected","2026-10-25").put("enabled",true).put("status","正在记录").put("nowTitle","晚风经过的地方").put("nowArtist","示例歌手 A").put("zone","Asia/Shanghai").put("summary",new JSONObject().put("ms",5280000).put("tracks",3).put("artists",3).put("days",1)).put("plays",24).put("daily",daily).put("recent",daily).put("timeline",daily).put("songs",daily).put("artists",new JSONArray()).put("heat",new JSONArray());}
    protected void layout(){View v=panel.getView();v.measure(View.MeasureSpec.makeMeasureSpec(1080,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(1900,View.MeasureSpec.EXACTLY));v.layout(0,0,1080,1900);}
    protected TextView find(View root,String target){if(root instanceof TextView&&((TextView)root).getText().toString().equals(target))return(TextView)root;if(root instanceof ViewGroup)for(int i=0;i<((ViewGroup)root).getChildCount();i++){TextView r=find(((ViewGroup)root).getChildAt(i),target);if(r!=null)return r;}return null;}
    @After public void stop(){if(panel!=null)panel.close();}
    @Test public void todayStartsWithSquareGalleryAndMinuteSummary(){assertNotNull(find(panel.getView(),"今天"));assertNotNull(find(panel.getView(),"88"));assertNotNull(find(panel.getView(),"聆听足迹"));assertEquals("day",lastPeriod);}
    @Test public void refreshDoesNotRebuildRootOrResetDataMode(){View before=panel.getView();int count=reports;find(before,"↻").performClick();assertSame(before,panel.getView());assertEquals(count+1,reports);assertNotNull(find(before,"播放顺序 ⌄"));}
    @Test public void historyKeepsSingleDayMeaning(){find(panel.getView(),"时光").performClick();layout();assertNotNull(find(panel.getView(),"一天的声音"));assertEquals("day",lastPeriod);}
    @Test public void preferencesHasDistinctNavigation(){find(panel.getView(),"偏好").performClick();layout();assertNotNull(find(panel.getView(),"反复心动"));assertNotNull(find(panel.getView(),"常在耳边的声音"));}
    @Test public void emptyAndZeroRemainReal()throws Exception{data.put("daily",new JSONArray()).put("recent",new JSONArray()).put("summary",new JSONObject().put("ms",0).put("tracks",0).put("artists",0));find(panel.getView(),"↻").performClick();layout();assertNotNull(find(panel.getView(),"0"));}
    @Test public void closingIsIdempotentAndReleases(){panel.close();panel.close();assertTrue(closed);}
    private TextView contains(View root,String target){if(root instanceof TextView&&((TextView)root).getText().toString().contains(target))return(TextView)root;if(root instanceof ViewGroup)for(int i=0;i<((ViewGroup)root).getChildCount();i++){TextView r=contains(((ViewGroup)root).getChildAt(i),target);if(r!=null)return r;}return null;}
    @Test public void sortSheetChangesPresentationWithoutChangingHistory()throws Exception{String before=data.getJSONArray("daily").toString();find(panel.getView(),"播放顺序 ⌄").performClick();android.app.Dialog dialog=org.robolectric.shadows.ShadowDialog.getLatestDialog();assertNotNull(dialog);TextView count=contains(dialog.getWindow().getDecorView(),"播放次数 · 相同歌曲合并");assertNotNull(count);count.performClick();org.robolectric.shadows.ShadowLooper.idleMainLooper(1,java.util.concurrent.TimeUnit.SECONDS);layout();assertNotNull(find(panel.getView(),"播放次数 ⌄"));assertEquals(before,data.getJSONArray("daily").toString());find(panel.getView(),"↻").performClick();assertNotNull(find(panel.getView(),"播放次数 ⌄"));}
    @Test public void datePickerIsCalendarNotRawTextField(){find(panel.getView(),"今天  ⌄").performClick();android.app.Dialog dialog=org.robolectric.shadows.ShadowDialog.getLatestDialog();assertNotNull(dialog);assertNotNull(contains(dialog.getWindow().getDecorView(),"回到今天"));assertNull(findType(dialog.getWindow().getDecorView(),EditText.class));}
    private View findType(View v,Class<?> type){if(type.isInstance(v))return v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){View r=findType(((ViewGroup)v).getChildAt(i),type);if(r!=null)return r;}return null;}
}

